  1	// Choosing where notes go — and, incidentally, the only way to create a folder.
  2	//
  3	// Neither type-core nor the desktop has a create-folder command: `move_items`
  4	// and `create_note` both `create_dir_all` their destination, which is why the
  5	// desktop's own move dialog says "Missing folders will be created". So this
  6	// picker is a list of existing folders *and* a path field, and typing a path
  7	// that does not exist yet is how a folder comes into being.
  8	
  9	import { Ionicons } from "@expo/vector-icons";
 10	import { useMemo, useState } from "react";
 11	import {
 12	  Modal,
 13	  Pressable,
 14	  ScrollView,
 15	  StyleSheet,
 16	  Text,
 17	  TextInput,
 18	  View,
 19	} from "react-native";
 20	import { useSafeAreaInsets } from "react-native-safe-area-context";
 21	
 22	import {
 23	  ARCHIEVE_FOLDER_PATH,
 24	  FEED_FOLDER_PATH,
 25	} from "@typenotes/shared/constants";
 26	import type { FolderNode } from "@typenotes/shared/types";
 27	
 28	import { allFolderPaths } from "../lib/folder-tree";
 29	import { useTheme } from "../theme";
 30	import { Button } from "./controls";
 31	
 32	/** Trim and collapse a typed path so "  Work / Q3 / " reads as "Work/Q3". */
 33	export const normalizeFolderPath = (value: string): string =>
 34	  value
 35	    .split("/")
 36	    .map((segment) => segment.trim())
 37	    .filter((segment) => segment.length > 0)
 38	    .join("/");
 39	
 40	export const FolderPickerModal = ({
 41	  visible,
 42	  tree,
 43	  heading,
 44	  onPick,
 45	  onClose,
 46	}: {
 47	  visible: boolean;
 48	  tree: FolderNode | null;
 49	  heading: string;
 50	  onPick: (destination: string) => void;
 51	  onClose: () => void;
 52	}) => {
 53	  const theme = useTheme();
 54	  const insets = useSafeAreaInsets();
 55	  const [typed, setTyped] = useState("");
 56	
 57	  const existing = useMemo(() => allFolderPaths(tree), [tree]);
 58	  const pinned = [FEED_FOLDER_PATH, ARCHIEVE_FOLDER_PATH].filter((path) =>
 59	    existing.includes(path)
 60	  );
 61	  const browsable = existing.filter((path) => !pinned.includes(path));
