type UseTreeInteractionsArgs = {
  /** The folders pane body; focused after a selection change. */
  foldersPanelRef: RefObject<HTMLDivElement | null>;
};

export type DesktopContextMenuState =
  | {
      kind: "folder";
      x: number;
      y: number;
      path: string;
      targetPaths: string[];
